from jsonb_populate_recordset(null::public.dapar_questions, '[{"id":"85c46f2d-8863-5260-a7f6-746150ddfc2c","domain":"verbal","layer":"application","skill":"יוצא דופן","difficulty":2,"prompt":"איזו מילה אינה שייכת לקבוצה?","instruction_text":"סמנו את המילה שאינה שייכת לקבוצה.","figure":null,"options":["לשמוע","להאזין","לדבר","להקשיב"],"correct_index":2,"explanation":"שלוש הפעולות קשורות לקליטת קול. לדבר היא הפקת קול.","source":"new","time_limit_seconds":30},{"id":"87bf6029-5b10-5318-ad3a-1fc77f180ecf","domain":"verbal","layer":"application","skill":"יוצא דופן","difficulty":3,"prompt":"איזו מילה אינה שייכת לקבוצה?","instruction_text":"סמנו את המילה שאינה שייכת לקבוצה.","figure":null,"options":["משולש","מחומש","ריבוע","עיגול"],"correct_index":3,"explanation":"משולש, ריבוע ומחומש הם מצולעים עם צלעות ישרות. לעיגול אין צלעות.","source":"new","time_limit_seconds":30},{"id":"bdfebcca-eddc-50d0-af64-d169bee27987","domain":"verbal","layer":"application","skill":"הבנת הנקרא","difficulty":1,"prompt":"מחקר שנערך בשלושה בתי ספר מצא שתלמידים שישנו לפחות שמונה שעות בלילה ענו נכון על יותר שאלות במבחן בוקר. החוקרים ציינו שהמחקר לא בדק מה התלמידים אכלו בבוקר.\n\nמה החוקרים ציינו כמגבלה של המחקר?","instruction_text":null,"figure":null,"options":["שהמחקר נערך רק בבית ספר אחד","שהמחקר לא בדק את ארוחת הבוקר","שהמבחן נערך בערב","ששינה של שמונה שעות מזיקה"],"correct_index":1,"explanation":"המשפט השני בקטע אומר זאת במפורש. שאר האפשרויות סותרות את הקטע (שלושה בתי ספר, מבחן בוקר) או לא כתובות בו.","source":"new","time_limit_seconds":90},{"id":"30f51da7-8360-5355-a314-674cb666b869","domain":"verbal","layer":"application","skill":"הבנת הנקרא","difficulty":2,"prompt":"בעבר האמינו שכל הברבורים לבנים, כי איש באירופה לא ראה ברבור בצבע אחר. כשהגיעו חוקרים לאוסטרליה, הם מצאו ברבורים שחורים.\n\nמה הרעיון המרכזי של הקטע?","instruction_text":null,"figure":null,"options":["חוקרים אירופים לא היו זהירים","באוסטרליה יש יותר ברבורים מבאירופה","כלל שנבנה מתצפיות בלבד יכול להתגלות כשגוי","ברבורים שחורים נדירים מאוד"],"correct_index":2,"explanation":"הקטע מראה כלל (\"כל הברבורים לבנים\") שהופרך בתצפית חדשה. שאר האפשרויות הן פרטים שלא כתובים בקטע.","source":"new","time_limit_seconds":90},{"id":"bf5d7979-1267-535f-ab46-ed2b9e3fcf49","domain":"verbal","layer":"application","skill":"הבנת הנקרא","difficulty":3,"prompt":"העירייה הציעה לסגור רחוב מרכזי לתנועת מכוניות. בעלי החנויות חששו שהקונים לא יגיעו. אחרי שנה, מספר הקונים ברחוב עלה, אך שתי חנויות שמכרו רהיטים כבדים נסגרו.\n\nאיזו טענה נתמכת בקטע?","instruction_text":null,"figure":null,"options":["הסגירה הועילה לרוב החנויות אך פגעה בחלק מהן","חששם של בעלי החנויות התברר כנכון לגמרי","העירייה תפתח את הרחוב מחדש","הסגירה פגעה בכל החנויות"],"correct_index":0,"explanation":"הקטע מציג גם עלייה בקונים וגם סגירה של שתי חנויות. טענה שמכילה את שני הצדדים היא המדויקת.","source":"new","time_limit_seconds":90},{"id":"5eed9baa-a89c-51e9-add4-961fa2b7d09d","domain":"instructions","layer":"knowledge","skill":"מילות מפתח","difficulty":1,"prompt":"\"לפחות 3 תשובות\" פירושו:","instruction_text":null,"figure":null,"options":["3 תשובות או פחות","3 תשובות או יותר","בדיוק 3 תשובות","פחות מ-3 תשובות"],"correct_index":1,"explanation":"\"לפחות\" קובע רצפה. 3 עומד בתנאי, וגם כל מספר גדול ממנו.","source":"new","time_limit_seconds":null},{"id":"7fb569a9-126f-5f2a-a90f-9f32ab271d37","domain":"instructions","layer":"knowledge","skill":"מילות מפתח","difficulty":1,"prompt":"\"לכל היותר 4 טעויות\" פירושו:","instruction_text":null,"figure":null,"options":["4 טעויות או פחות","יותר מ-4 טעויות","4 טעויות או יותר","בדיוק 4 טעויות"],"correct_index":0,"explanation":"\"לכל היותר\" קובע תקרה. 4 עומד בתנאי, וגם כל מספר קטן ממנו.","source":"new","time_limit_seconds":null},{"id":"e538d086-e386-5c9c-aad7-44ef4a4a856e","domain":"instructions","layer":"knowledge","skill":"מילות מפתח","difficulty":1,"prompt":"הוראה: \"סמנו את התשובה שאינה נכונה\". מה מחפשים?","instruction_text":null,"figure":null,"options":["את התשובה הארוכה","את כל התשובות הנכונות","את התשובה השגויה","את התשובה הנכונה"],"correct_index":2,"explanation":"המילה \"אינה\" הופכת את המשימה. מסמנים אותה לפני הפתרון כדי לא לחפש את ההפך.","source":"new","time_limit_seconds":null},{"id":"3ffffaf5-1fe1-5093-a97a-f76fd27fb004","domain":"instructions","layer":"knowledge","skill":"מילות מפתח","difficulty":1,"prompt":"\"יותר מ-5\" כולל את 5?","instruction_text":null,"figure":null,"options":["כן, אבל רק אם 5 זוגי","לא, רק 6 ומעלה (במספרים שלמים)","כן, 5 ומעלה","תלוי בשאלה"],"correct_index":1,"explanation":"\"יותר מ\" לא כולל את המספר עצמו. \"לפחות\" כן כולל.","source":"new","time_limit_seconds":null},{"id":"ef5f4356-3cb3-5734-a714-1f825e0d0989","domain":"instructions","layer":"knowledge","skill":"מילות מפתח","difficulty":1,"prompt":"\"פחות מ-3 טעויות\". האם 3 טעויות עומדות בתנאי?","instruction_text":null,"figure":null,"options":["אי אפשר לדעת","כן","לא","רק אם הן מאותו סוג"],"correct_index":2,"explanation":"\"פחות מ-3\" פירושו 0, 1 או 2. שלוש כבר לא עומד בתנאי.","source":"new","time_limit_seconds":null},{"id":"7e05f1e6-0bf2-5cf7-a3f0-889e848cd5c1","domain":"instructions","layer":"knowledge","skill":"מילות מפתח","difficulty":1,"prompt":"ברצף 4, 7, 1, 9, 5, מהו \"המספר השני מהסוף\"?","instruction_text":null,"figure":null,"options":["1","5","7","9"],"correct_index":3,"explanation":"סופרים מהסוף: הראשון מהסוף הוא 5, השני מהסוף הוא 9.","source":"new","time_limit_seconds":null},{"id":"3a2c3e52-81a1-577f-a889-38ffe2f93026","domain":"instructions","layer":"knowledge","skill":"מילות מפתח","difficulty":1,"prompt":"בקבוצה 2, 3, 4, 5, 8, אילו מספרים \"אינם זוגיים\"?","instruction_text":null,"figure":null,"options":["3 ו-5","2, 4 ו-8","רק 3","רק 5"],"correct_index":0,"explanation":"\"אינם זוגיים\" הם האי זוגיים: 3 ו-5.","source":"new","time_limit_seconds":null},{"id":"58fd57d3-9c5d-56e0-a6c1-a8d36254af9d","domain":"instructions","layer":"knowledge","skill":"מילות מפתח","difficulty":1,"prompt":"מה עושים קודם כשמקבלים הוראה במבחן?","instruction_text":null,"figure":null,"options":["מדלגים על ההוראה וקו